<template>
  <CanvasserFormWrapper title="Edit Profile">
    <AppLoader v-if="isLoading && !profileDetails" subject="profile" />
    <AppError v-else-if="error" :error="error" title="Failed to load profile" />
    <ProfileEditForm
      v-else
      :initial-data="initialData"
      :can-edit-bio-text="canEdit"
      guard-unsaved-changes
      :is-saving="isSaving"
      :on-submit="onSubmit"
    />
  </CanvasserFormWrapper>
</template>

<script lang="ts" setup>
import { canEditBioText } from '~/utils/profileEditPermissions';
import { profileAnswersFromDetails } from '~/utils/profileAnswersFromDetails';
import { useProfileDetails } from '~/queries/users/profile';

// The account/edit.vue layout passes :account-info, which this page does not need
// (it fetches profile details by the current user's id instead).
defineOptions({ inheritAttrs: false });

useHead({ title: 'Edit Profile' });

const { userRole, userId } = useUserRole();
const canEdit = computed(() => canEditBioText('self', userRole.value));

const { profileDetails, isLoading, error } = useProfileDetails(userId);

const initialData = computed(() => ({
  profile_picture_url: profileDetails.value?.profile_picture_url ?? null,
  bio: profileDetails.value?.bio ?? null,
  answers: profileAnswersFromDetails(profileDetails.value),
}));

// Same endpoint as admin edit; the composable passes the current user's own id for a self-edit.
const { onSubmit, isSaving } = useProfileEditSubmit('self', userId, initialData);
</script>
